const input = $json;
const body = input.body || input;

const EXPECTED_TOKEN =
  'YOUR_PLN_FINALIZE_TRIGGER_TOKEN';

if (String(body.token || '') !== EXPECTED_TOKEN) {
  throw new Error('UNAUTHORIZED_FINALIZATION: Token finalisasi tidak valid');
}

const fileId = String(body.file_id || body.spreadsheet_id || '').trim();

if (!/^[A-Za-z0-9_-]{15,}$/.test(fileId)) {
  throw new Error('INVALID_REPORT_FILE_ID: ID spreadsheet tidak valid (' + fileId + ')');
}

return {
  json: {
    authorized: true,
    file_id: fileId,
    action: 'finalize_pdf'
  }
};

// Ambil data output dari node sebelumnya (Prepare Reviewed PDF1)
const raw = $input.first().json || {};
let p = raw.body ?? raw;

if (typeof p === 'string') {
  try {
    p = JSON.parse(p);
  } catch (e) {
    throw new Error('APPS_SCRIPT_NON_JSON_RESPONSE: ' + p.slice(0, 400));
  }
}

if (p.ok !== true || p.status !== 'PREPARED') {
  throw new Error('PREPARE_FAILED: ' + JSON.stringify(p).slice(0, 1000));
}

const tnId = String(p.tn_pdf_file_id || '').trim();
const compId = String(p.comparison_pdf_file_id || '').trim();
const hitungId = String(p.hitung_pdf_file_id || '').trim();
const invoiceId = String(p.original_pdf_file_id || p.source_file_id || '').trim();
const folderId = String(p.output_folder_id || '').trim();
const reportFileId = String(p.file_id || '').trim();

if (!tnId || !compId || !reportFileId || !folderId) {
  throw new Error('PDF_INPUTS_OR_METADATA_MISSING: ' + JSON.stringify(p).slice(0, 1000));
}

const filename = String(p.final_pdf_name || 'PLN_FINAL_REPORT.pdf')
  .replace(/\.pdf$/i, '')
  .replace(/[\\/:*?"<>|]/g, '_') + '.pdf';

const items = [
  {
    json: {
      order: 1,
      type: 'TN',
      file_id: tnId,
      report_file_id: reportFileId,
      customer_id: p.customer_id,
      final_pdf_name: filename,
      output_folder_id: folderId
    }
  },
  {
    json: {
      order: 2,
      type: 'COMPARISON',
      file_id: compId,
      report_file_id: reportFileId,
      customer_id: p.customer_id,
      final_pdf_name: filename,
      output_folder_id: folderId
    }
  }
];

let nextOrder = 3;
if (hitungId) {
  items.push({
    json: {
      order: nextOrder++,
      type: 'HITUNG',
      file_id: hitungId,
      report_file_id: reportFileId,
      customer_id: p.customer_id,
      final_pdf_name: filename,
      output_folder_id: folderId
    }
  });
}

if (invoiceId) {
  items.push({
    json: {
      order: nextOrder,
      type: 'INVOICE',
      file_id: invoiceId,
      report_file_id: reportFileId,
      customer_id: p.customer_id,
      final_pdf_name: filename,
      output_folder_id: folderId
    }
  });
}

return items;

let PDFDocument;
try {
  const pdflib = require('pdf-lib');
  PDFDocument = pdflib.PDFDocument;
} catch (err) {
  throw new Error('MODULE_PDF_LIB_NOT_FOUND: ' + err.message);
}

const items = $input.all();
if (!items || items.length === 0) {
  throw new Error('NO_PDF_ITEMS_RECEIVED');
}

// 1. Urutkan: 1. TN, 2. COMPARISON, 3. HITUNG (jika ada), 4. INVOICE
items.sort((a, b) => (Number(a.json.order) || 0) - (Number(b.json.order) || 0));

if (items.length < 2) {
  throw new Error(`Diharapkan minimal 2 PDF, menerima ${items.length} item.`);
}

const mergedPdf = await PDFDocument.create();

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const itemType = String(item.json.type || '').toUpperCase();
  const buffer = await this.helpers.getBinaryDataBuffer(i, 'data');

  if (!buffer || buffer.length < 50 || buffer.subarray(0, 5).toString() !== '%PDF-') {
    throw new Error(`INVALID_PDF_BUFFER: Dokumen "${itemType}" bukan file PDF valid.`);
  }

  const sourcePdf = await PDFDocument.load(buffer, { ignoreEncryption: true });
  const indices = sourcePdf.getPageIndices();

  // Untuk sheet internal (TN, COMPARISON, HITUNG): kunci hanya 1 halaman
  if ((itemType === 'TN' || itemType === 'COMPARISON' || itemType === 'HITUNG') && indices.length > 1) {
    indices.length = 1;
  }

  const copiedPages = await mergedPdf.copyPages(sourcePdf, indices);
  copiedPages.forEach((page) => mergedPdf.addPage(page));
}

// Simpan PDF yang sudah bersih dari lembar instruksi
const mergedPdfBytes = await mergedPdf.save();
const meta = items[0].json;
const finalFilename = meta.final_pdf_name || 'PLN_FINAL_REPORT.pdf';

const binaryData = await this.helpers.prepareBinaryData(
  Buffer.from(mergedPdfBytes),
  finalFilename,
  'application/pdf'
);

return [{
  json: {
    file_id: meta.report_file_id || meta.file_id,
    customer_id: meta.customer_id,
    final_pdf_name: finalFilename,
    output_folder_id: meta.output_folder_id,
    pdf_size_bytes: mergedPdfBytes.length,
    total_pages: mergedPdf.getPageCount()
  },
  binary: {
    data: binaryData
  }
}];

