const raw = $input.item.json || {};
let r = raw.body ?? raw;
if (typeof r === 'string') {
  try {
    r = JSON.parse(r);
  } catch (e) {
    throw new Error('FINALIZE_NON_JSON_RESPONSE: ' + r.slice(0, 300));
  }
}

if (r.ok !== true) {
  throw new Error('FINALIZE_FAILED: ' + JSON.stringify(r));
}

const status = String(r.status || '').toUpperCase();
if (!['COMPLETED', 'FINALIZED', 'ALREADY_FINALIZED'].includes(status)) {
  throw new Error('INVALID_FINAL_STATUS: ' + status);
}

const reportId = String(
  r.file_id || r.sheet_id || $('Merge PDFs with pdf-lib').first().json.file_id || ''
).trim();
const uploadedId = String($('Upload Final Merged PDF1').first().json.id || '').trim();
const finalPdfId = String(r.final_pdf_id || r.pdf_file_id || uploadedId).trim();

if (!reportId || !finalPdfId) {
  throw new Error('REPORT_OR_FINAL_PDF_ID_MISSING');
}

if (uploadedId && finalPdfId !== uploadedId) {
  throw new Error('FINALIZED_PDF_ID_MISMATCH');
}

const pdfUrl = String(r.pdf_url || `https://drive.google.com/file/d/${finalPdfId}/view`).trim();
if (!/^https:\/\/drive\.google\.com\//.test(pdfUrl)) {
  throw new Error('INVALID_PDF_URL: ' + pdfUrl);
}

const mergeInfo = $('Merge PDFs with pdf-lib').first().json;

return {
  json: {
    ok: true,
    status: 'COMPLETED',
    report_status: 'COMPLETED',
    converter: 'pdf-lib',
    file_id: reportId,
    final_pdf_id: finalPdfId,
    pdf_url: pdfUrl,
    pdf_name: mergeInfo.final_pdf_name,
    total_pages: mergeInfo.total_pages,
    size_bytes: mergeInfo.pdf_size_bytes,
    message: 'PLN report successfully merged locally via pdf-lib and finalized.'
  }
};
